// Kontrollerar F25 "Besök Vreta": märkning, fullbokat-budskapet, Barkens utelämnanden (k-112), inga externa resurser,
// och F34: interna länkar utan .html (vercel.json har cleanUrls).
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const html = fs.readFileSync('public/besok-vreta.html', 'utf8');
const utanKommentarer = html.replace(/<!--[\s\S]*?-->/g, '');
const krav = {
  svenska: /<html lang="sv">/.test(html),
  titel: /<title>Besök Vreta – luminusloom\.net<\/title>/.test(html),
  hopplankForst: html.indexOf('class="hoppa"') > -1 && html.indexOf('class="hoppa"') < html.indexOf('<header'),
  aiEtiketter: (html.match(/class="etikett">AI-skapat</g) || []).length >= 2,
  signatur: (html.match(/Generated by AI, Directed by MS/g) || []).length >= 2,
  fullbokatOrdagrant: html.includes('Bokning av övernattning och aktiviteter är fullbokad fram till sommaren 2027.'),
  personerMarkta: html.includes('Båda är AI-skapade personer'),
  ombyggnadPagar: html.includes('Ombyggnad pågår'),
  ingaPriser: !/\d\s?(kr|SEK)\b/.test(html),
  ingaDriveId: !/drive\.google|freja_bild|referensbild/i.test(utanKommentarer),
  ingaSovrum: !/sovrum|badrum|dusch|toalett|kvm/i.test(utanKommentarer),
  ingenVeckomeny: !/vecka 46|veckomeny v/i.test(html),
  ingenKontakt: !/mailto:|tel:/i.test(html),
  ingaExterna: !/(src|href)="https?:\/\//.test(html) && !/@import|url\(/.test(html),
  ingetSkript: !/<script/i.test(html),
  morktLage: html.includes('prefers-color-scheme: dark'),
  renaLankar: !/href="\/[^"]*\.html"/.test(utanKommentarer),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
